# 7a. allowlist_addon.py (static content; safe to overwrite on every run)
cat >"$CONFIG_DIR/allowlist_addon.py" <<'ADDON_EOF'
"""
mitmproxy addon for agent-sandbox — host allowlist enforcement.

Reads ~/.config/agent-sandbox/allowlist.txt on every request and lets
through only hosts that match. Lines are exact hostnames; a leading dot
(".github.com") makes the line match the host AND its subdomains.

Per-session additions (`agent-sandbox --allow HOST`) are read from
<session base>/session.*/allow.txt, where <session base> is
$AGENT_SANDBOX_SESSION_BASE, else $XDG_RUNTIME_DIR/agent-sandbox.<uid>,
else /tmp/agent-sandbox.<uid> -- the same rule the engine uses. A session's
allow.txt is honoured only while the process stamped in its owner.id
("<pid> <start-time>") is alive, so a session that dies without cleaning up
cannot leave a host open, and a recycled PID is never mistaken for the
owner. Note the proxy is shared: while a session lives, its --allow hosts
are reachable from every concurrent session.

Blocked requests return HTTP 403 and are logged to
~/.config/agent-sandbox/blocked.log (one line per attempt) so you can
review what the agent tried to reach and decide whether to add it.
A refusal that belongs to a live session is ALSO appended to that session's own
<session dir>/refused.log, when the engine created one ("<ts>\t<host>\t<method>\t<why>",
why one of allowlist, [deny], retrieve-only, git refuse, git push, non-public): the
engine binds that one file read-only into the sandbox, so the session learns at
once what it was refused (the claude profile's PostToolUse hook reports it).
blocked.log itself records every session of every project and is never bound in.

Per-session --allow is scoped to its own session, not shared: the engine gives
each session that uses --allow a random token, points that sandbox's proxy URL
at http://<token>@127.0.0.1:8888, and stores the token in the session dir. A
request carries the token in its Proxy-Authorization header (on CONNECT for
HTTPS, on each request for plain HTTP); the addon maps it back to the one live
session and applies the global allowlist plus ONLY that session's --allow. So
one session's --allow is never reachable from another. The global
allowlist.txt still applies to everyone.

A REQUEST BELONGS TO A LIVE SESSION, OR IT IS REFUSED. The token is also what a
session's subtractions hang on -- its [deny], retrieve-only and git refusal -- and
for a subtraction an anonymous client is the widest one: a request without a token
used to get the global allowlist, so a client that did not send it (git, whose
libcurl waits for a challenge) or an agent that dropped it from HTTPS_PROXY was out
of reach of all three (measured on mitmproxy 12.2.2). A request with no token, or
with the token of a session that is not alive, gets 407 Proxy Authentication
Required with a Basic challenge, on CONNECT and on a plain request alike: a client
holding the credentials in its proxy URL then sends them (measured: git retries the
CONNECT with them), and one without has nothing to send. The engine mints a token
for every proxied launch.

A session whose dir holds hosts-public.txt ([net] hosts = public) is not gated by
the allowlist: every host passes it. Its [deny], retrieve-only and git refusals
still apply, and so does the non-public refusal in `server_connect`, so it reaches
every PUBLIC host and nothing on this machine or its LAN.

No restart needed when editing the allowlist; the file is re-read on
each request.

The allowlist decides on the destination the proxy actually dials, not on a
client-supplied Host header: `GET http://<dest>/` with `Host: <allowlisted>`
is judged on <dest>. And because the proxy runs on the host, a destination that
resolves to a non-public address -- loopback, a private LAN, link-local (cloud
metadata) -- is refused before the socket opens, even if its NAME is on the
allowlist (an allowlisted name that resolves to loopback, or a public name under
DNS rebinding, would otherwise reach a host-local service). See `server_connect`.

HTTPS is refused at the CONNECT stage for hosts not in the allowlist, so a
blocked host never sees a connection from this machine (mitmproxy would
otherwise open a TCP+TLS connection to it, to mirror its certificate, before
the inner request could be checked). The client sees "CONNECT tunnel
failed, response 403"; blocked.log records the host with method CONNECT.
Requests inside an allowed tunnel are still checked per request, so paths
are logged and a Host header naming another host is refused.

Response bodies are streamed to the client as they arrive instead of being
buffered to completion (mitmproxy's default), and the systemd unit runs
mitmdump with http2=false. Together these take downloads and streaming LLM
replies from ~1 MB/s with the first byte at the very end to near-native
speed. Nothing here inspects response bodies, so streaming costs nothing;
every allowlist decision is made before a body flows.
"""

from __future__ import annotations

import base64
import datetime
import ipaddress
import logging
import os
import socket
from pathlib import Path

from mitmproxy import http


CONFIG_DIR = Path.home() / ".config" / "agent-sandbox"
ALLOWLIST_PATH = CONFIG_DIR / "allowlist.txt"
BLOCKED_LOG_PATH = CONFIG_DIR / "blocked.log"

logger = logging.getLogger(__name__)


def _session_base() -> Path:
    override = os.environ.get("AGENT_SANDBOX_SESSION_BASE")
    if override:
        return Path(override)
    runtime = Path(os.environ.get("XDG_RUNTIME_DIR") or f"/run/user/{os.getuid()}")
    # Match the engine's _as_session_base: it falls back to /tmp when the runtime
    # dir is not a writable directory, so require writability here too, or the
    # addon would look in a different base and silently ignore --allow.
    if not (runtime.is_dir() and os.access(runtime, os.W_OK)):
        runtime = Path("/tmp")
    return runtime / f"agent-sandbox.{os.getuid()}"


SESSION_BASE = _session_base()


def _owner_alive(owner_file: Path) -> bool:
    """True iff the process stamped in owner.id ("<pid> <start-time>") still runs.

    The start-time (field 22 of /proc/<pid>/stat) is compared too, so a
    recycled PID is never mistaken for the original owner.
    """
    try:
        pid, start = owner_file.read_text().split()[:2]
        stat = Path(f"/proc/{int(pid)}/stat").read_text()
    except (OSError, ValueError):
        return False
    fields = stat.rsplit(")", 1)[1].split()  # fields after "(comm)"; [0] is field 3
    return len(fields) > 19 and fields[19] == start


# CONNECT establishes an HTTPS tunnel; the token rides its Proxy-Authorization
# header, but the requests inside the tunnel do not resend it. Remember, per
# client connection, the token seen at CONNECT so those inner requests inherit
# it. Bounded by concurrent client connections; entries are dropped on disconnect.
_conn_token: dict[str, str] = {}


def _token_from(flow: http.HTTPFlow) -> str | None:
    """The session token in a request's Proxy-Authorization (Basic <b64 token:>),
    or None. The username field is the token; the password is unused."""
    try:
        auth = flow.request.headers.get("Proxy-Authorization")
    except Exception:
        return None
    if not auth or not auth.lower().startswith("basic "):
        return None
    try:
        user = base64.b64decode(auth.split(" ", 1)[1]).decode().split(":", 1)[0]
    except Exception:
        return None
    return user or None


def _strip_proxy_auth(flow: http.HTTPFlow) -> None:
    """Never forward the session token upstream."""
    try:
        if "Proxy-Authorization" in flow.request.headers:
            del flow.request.headers["Proxy-Authorization"]
    except Exception:
        pass


def _session_allow(token: str | None) -> list[str]:
    """--allow lines of the single live session whose proxy.token matches `token`.
    No token, or no live match, means no per-session grants (global list only), so
    one session's --allow is never visible to another."""
    return _session_lines(token, "allow.txt")


def _session_deny(token: str | None) -> list[str]:
    """[deny] lines of the live session whose proxy.token matches `token` (#221):
    hosts taken out of what the global allowlist and the session's own grant, for
    that session only. The engine has already left out any that would take a host
    the agent's profile needs."""
    return _session_lines(token, "deny.txt")


def _session_retrieve_only(token: str | None) -> list[str] | None:
    """The live session's retrieve-only exemptions (#223), or None when it is not
    retrieve-only. The file's presence turns it on; its lines are the hosts it does
    not apply to -- the agent profile's own (its API), which the agent cannot work
    without."""
    if not token or not SESSION_BASE.is_dir():
        return None
    for session in sorted(SESSION_BASE.glob("session.*")):
        tok, ro, owner = session / "proxy.token", session / "retrieve-only.txt", session / "owner.id"
        try:
            if tok.is_file() and owner.is_file() and tok.read_text().strip() == token and _owner_alive(owner):
                return ro.read_text().splitlines() if ro.is_file() else None
        except OSError:
            continue
    return None


# GraphQL, for `gh` (#223): it reads issues and pull requests by POSTing a query to
# api.github.com/graphql, and writes them by POSTing a mutation to the same place.
GRAPHQL_HOSTS = {"api.github.com"}
GRAPHQL_PATHS = {"/graphql", "/api/graphql"}


def _graphql_strip(doc: str) -> str:
    """A GraphQL document with its strings and comments removed, so a keyword can
    only be matched where it is syntax."""
    out, i, n = [], 0, len(doc)
    while i < n:
        if doc.startswith('"""', i):
            j = doc.find('"""', i + 3)
            i = n if j < 0 else j + 3
        elif doc[i] == '"':
            j = i + 1
            while j < n and doc[j] != '"':
                j += 2 if doc[j] == "\\" else 1
            i = j + 1
        elif doc[i] == "#":
            j = doc.find("\n", i)
            i = n if j < 0 else j
        else:
            out.append(doc[i])
            i += 1
    return "".join(out)


def _graphql_reads_only(body: bytes) -> bool:
    """True when every operation in a GraphQL request body is a query. A mutation
    or a subscription anywhere in a document refuses it, whichever operation the
    request names: conservative, since a document is cheap to resend as a query.
    A body that is not a GraphQL request refuses too."""
    import json
    import re

    try:
        payload = json.loads(body or b"null")
    except ValueError:
        return False
    items = payload if isinstance(payload, list) else [payload]
    if not items:
        return False
    for item in items:
        doc = item.get("query") if isinstance(item, dict) else None
        if not isinstance(doc, str):
            return False
        if re.search(r"\b(mutation|subscription)\b", _graphql_strip(doc)):
            return False
    return True


def _retrieve_refusal(flow: http.HTTPFlow, token: str | None) -> str | None:
    """Why a retrieve-only session's request is refused, or None to let it pass."""
    exempt = _session_retrieve_only(token)
    if exempt is None:
        return None
    host, method = flow.request.host, flow.request.method.upper()
    ex_exact: set[str] = set()
    ex_suffix: list[str] = []
    _parse(exempt, ex_exact, ex_suffix)
    if _is_allowed(host, ex_exact, ex_suffix):
        return None
    if _is_git_push(flow):  # whatever [net] git says: a retrieve-only session never pushes
        return "a git push (this session is retrieve-only: it reads, it does not publish)"
    # A fetch reads, as a query does (#280); the request handler refused it already
    # where [net] git = refuse.
    if method in ("GET", "HEAD") or _is_git_fetch(flow):
        return None
    if method == "POST" and host in GRAPHQL_HOSTS and flow.request.path.split("?", 1)[0] in GRAPHQL_PATHS:
        if _graphql_reads_only(getattr(flow.request, "content", b"")):
            return None
        return "a GraphQL mutation (this session is retrieve-only: it reads, it does not publish)"
    return f"{method} (this session is retrieve-only: GET and HEAD only)"


def _session_live(token: str | None) -> bool:
    """Is `token` the token of a live session? The one identity the proxy has."""
    if not token or not SESSION_BASE.is_dir():
        return False
    for session in sorted(SESSION_BASE.glob("session.*")):
        tok, owner = session / "proxy.token", session / "owner.id"
        try:
            if tok.is_file() and owner.is_file() and tok.read_text().strip() == token and _owner_alive(owner):
                return True
        except OSError:
            continue
    return False


def _session_dir(token: str | None) -> Path | None:
    """The directory of the live session whose proxy.token matches `token`, or None."""
    if not token or not SESSION_BASE.is_dir():
        return None
    for session in sorted(SESSION_BASE.glob("session.*")):
        tok, owner = session / "proxy.token", session / "owner.id"
        try:
            if tok.is_file() and owner.is_file() and tok.read_text().strip() == token and _owner_alive(owner):
                return session
        except OSError:
            continue
    return None


def _session_has(token: str | None, name: str) -> bool:
    """Does the live session whose proxy.token matches `token` have the file `name`?"""
    if not token or not SESSION_BASE.is_dir():
        return False
    for session in sorted(SESSION_BASE.glob("session.*")):
        tok, f, owner = session / "proxy.token", session / name, session / "owner.id"
        try:
            if tok.is_file() and owner.is_file() and tok.read_text().strip() == token and _owner_alive(owner):
                return f.is_file()
        except OSError:
            continue
    return False


def _refuse_anonymous(flow: http.HTTPFlow, host: str, method: str, path: str) -> None:
    """407 with a Basic challenge, for a request that belongs to no live session."""
    _log_blocked(host, method, path, "no session")
    flow.response = http.Response.make(
        407,
        (
            f"agent-sandbox: a request to {host!r} with no live session's token. The proxy serves\n"
            "agent-sandbox sessions only, which carry theirs in the proxy URL.\n"
        ).encode(),
        {"Content-Type": "text/plain; charset=utf-8", "Proxy-Authenticate": 'Basic realm="agent-sandbox"'},
    )


GIT_SERVICES = ("git-upload-pack", "git-receive-pack")


def _is_git_transport(flow: http.HTTPFlow) -> bool:
    """Git's smart-HTTP transport (#224): the ref advertisement
    (`/info/refs?service=git-upload-pack|git-receive-pack`), the pack endpoints
    (`.../git-upload-pack`, `.../git-receive-pack`), or anything git itself sends
    (`User-Agent: git/...`), whichever host it goes to."""
    path, _, query = flow.request.path.partition("?")
    if path.endswith("/info/refs") and any(f"service={svc}" in query for svc in GIT_SERVICES):
        return True
    if path.endswith(tuple("/" + svc for svc in GIT_SERVICES)):
        return True
    ua = ""
    try:
        ua = flow.request.headers.get("User-Agent", "") or ""
    except Exception:
        pass
    return ua.lower().startswith("git/")


def _is_git_push(flow: http.HTTPFlow) -> bool:
    """Git's smart-HTTP PUSH: the receive-pack advertisement or endpoint. A fetch
    (upload-pack) is not one."""
    path, _, query = flow.request.path.partition("?")
    if path.endswith("/info/refs") and "service=git-receive-pack" in query:
        return True
    return path.endswith("/git-receive-pack")


def _is_git_fetch(flow: http.HTTPFlow) -> bool:
    """Git's smart-HTTP FETCH (#280): the upload-pack advertisement or endpoint, by its
    path, not by git's user agent -- a user agent says nothing about what a POST does."""
    if _is_git_push(flow):
        return False
    path, _, query = flow.request.path.partition("?")
    if path.endswith("/info/refs") and "service=git-upload-pack" in query:
        return True
    return path.endswith("/git-upload-pack")


def _session_lines(token: str | None, name: str) -> list[str]:
    if not token or not SESSION_BASE.is_dir():
        return []
    for session in sorted(SESSION_BASE.glob("session.*")):
        tok, allow, owner = session / "proxy.token", session / name, session / "owner.id"
        try:
            if (
                tok.is_file()
                and allow.is_file()
                and owner.is_file()
                and tok.read_text().strip() == token
                and _owner_alive(owner)
            ):
                return allow.read_text().splitlines()
        except OSError:
            continue
    return []


def _parse(lines: list[str], exact: set[str], suffix: list[str]) -> None:
    """Add allowlist lines to (exact_hosts, suffix_patterns).

    A line "github.com" matches only "github.com".
    A line ".github.com" matches "github.com" and "*.github.com".
    """
    for raw in lines:
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        if line.startswith("."):
            exact.add(line[1:])
            suffix.append(line)
        else:
            exact.add(line)


def _is_denied(host: str, token: str | None) -> bool:
    exact: set[str] = set()
    suffix: list[str] = []
    _parse(_session_deny(token), exact, suffix)
    return _is_allowed(host, exact, suffix)


def _load_allowlist(token: str | None = None) -> tuple[set[str], list[str]]:
    exact: set[str] = set()
    suffix: list[str] = []
    if ALLOWLIST_PATH.exists():
        _parse(ALLOWLIST_PATH.read_text().splitlines(), exact, suffix)
    _parse(_session_allow(token), exact, suffix)
    return exact, suffix


def _is_allowed(host: str, exact: set[str], suffix: list[str]) -> bool:
    if host in exact:
        return True
    return any(host.endswith(s) for s in suffix)


def _addr_is_public(ip: str) -> bool:
    """True iff `ip` is a globally routable address. Loopback, private, link-local,
    unique-local, unspecified, multicast and reserved ranges are all non-public."""
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False
    if isinstance(addr, ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        addr = addr.ipv4_mapped
    return addr.is_global


def _forbidden_destination(host: str) -> str | None:
    """A reason string if connecting to `host` would reach a non-public address,
    else None.

    The proxy runs on the host, so a destination that resolves to loopback,
    a private LAN, link-local (cloud metadata at 169.254.169.254) or the like is
    never a legitimate allowlist target -- yet the allowlist gates the NAME, so an
    allowlisted name that resolves to such an address (localhost, or a public name
    under DNS rebinding) would otherwise reach a host-local service. This is the
    destination-IP check the name gate cannot do.

    A resolution failure returns None (not forbidden): there is nothing to reach,
    and mitmproxy's own connect will fail it. Only an address that resolves and is
    non-public is refused.
    """
    try:
        ipaddress.ip_address(host)  # already a literal IP?
        candidates = [host]
    except ValueError:
        try:
            candidates = [ai[4][0] for ai in socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)]
        except OSError:
            return None
    for ip in candidates:
        if not _addr_is_public(ip):
            return f"{ip} (from {host})" if ip != host else ip
    return None


def _log_blocked(host: str, method: str, path: str, why: str = "") -> None:
    BLOCKED_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
    ts = datetime.datetime.now().isoformat(timespec="seconds")
    with BLOCKED_LOG_PATH.open("a") as fh:
        fh.write(f"{ts}\t{host}\t{method}\t{path}" + (f"\t{why}" if why else "") + "\n")


def _log_refused(token: str | None, host: str, method: str, why: str) -> None:
    """Append a refusal to its session's own refused.log, which the engine binds
    read-only into that sandbox. Only when the engine created the file (the
    session's briefing is on), and best-effort: a failure to write never changes
    the response."""
    try:
        session = _session_dir(token)
        if session is None:
            return
        log = session / "refused.log"
        if not log.is_file():
            return
        ts = datetime.datetime.now().isoformat(timespec="seconds")
        with log.open("a") as fh:
            fh.write(f"{ts}\t{host}\t{method}\t{why}\n")
    except OSError:
        pass


def request(flow: http.HTTPFlow) -> None:
    # flow.request.host is the request-line authority -- where mitmproxy actually
    # opens the connection. pretty_host would return the Host HEADER instead, and
    # a client can send any Host header it likes: `GET http://dest/` with
    # `Host: <allowlisted>` made pretty_host allowlisted while the connection went
    # to dest, bypassing egress entirely for plain HTTP. Gate the connect target.
    host = flow.request.host
    token = _token_from(flow)
    if token is None:  # inner request of an HTTPS tunnel: inherit the CONNECT's token
        cid = getattr(getattr(flow, "client_conn", None), "id", None)
        token = _conn_token.get(cid) if cid is not None else None
    _strip_proxy_auth(flow)
    if not _session_live(token):
        _refuse_anonymous(flow, host, flow.request.method, flow.request.path)
        return
    if _is_denied(host, token):
        _log_blocked(host, flow.request.method, flow.request.path)
        _log_refused(token, host, flow.request.method, "[deny]")
        flow.response = http.Response.make(
            403,
            f"agent-sandbox: host {host!r} is denied for this session ([deny] in .agent-sandbox).\n".encode(),
            {"Content-Type": "text/plain; charset=utf-8"},
        )
        return
    exact, suffix = _load_allowlist(token)
    if _is_allowed(host, exact, suffix) or _session_has(token, "hosts-public.txt"):
        # The git lines first: retrieve-only passes git's fetch (#280), so [net] git = refuse
        # must have refused it already, and a push under git = fetch is named as one.
        if _is_git_transport(flow) and _session_has(token, "git-refuse.txt"):
            why, reason = "git's transport (this session's [net] git = refuse)", "git refuse"
        elif _is_git_push(flow) and _session_has(token, "git-push-refuse.txt"):
            why, reason = "a git push (this session's [net] git = fetch: it fetches, it does not push)", "git push"
        else:
            why, reason = _retrieve_refusal(flow, token), "retrieve-only"
        if why is None:
            return
        _log_blocked(host, flow.request.method, flow.request.path)
        _log_refused(token, host, flow.request.method, reason)
        flow.response = http.Response.make(
            403,
            f"agent-sandbox: {why} to {host!r} refused.\n".encode(),
            {"Content-Type": "text/plain; charset=utf-8"},
        )
        return
    _log_blocked(host, flow.request.method, flow.request.path)
    _log_refused(token, host, flow.request.method, "allowlist")
    flow.response = http.Response.make(
        403,
        (
            f"agent-sandbox: host {host!r} is not in the allowlist.\n"
            f"To allow it, add a line to {ALLOWLIST_PATH}:\n"
            f"    {host}        (exact)\n"
            f"    .{host}       (and all subdomains)\n"
            f"or relaunch with:  --allow {host}   (this session only)\n"
        ).encode(),
        {"Content-Type": "text/plain; charset=utf-8"},
    )


def client_disconnected(client) -> None:
    _conn_token.pop(getattr(client, "id", None), None)


def http_connect(flow: http.HTTPFlow) -> None:
    """Refuse CONNECT to a non-allowed host before any upstream connection."""
    host = flow.request.host
    token = _token_from(flow)
    cid = getattr(getattr(flow, "client_conn", None), "id", None)
    if cid is not None and token:
        _conn_token[cid] = token  # inner tunnel requests inherit this
    _strip_proxy_auth(flow)
    if not _session_live(token):
        _refuse_anonymous(flow, host, "CONNECT", "-")
        return
    denied = _is_denied(host, token)
    exact, suffix = _load_allowlist(token)
    if not denied and (_is_allowed(host, exact, suffix) or _session_has(token, "hosts-public.txt")):
        return
    _log_blocked(host, "CONNECT", "-")
    _log_refused(token, host, "CONNECT", "[deny]" if denied else "allowlist")
    why = "denied for this session ([deny] in .agent-sandbox)" if denied else "not in the allowlist"
    flow.response = http.Response.make(
        403,
        f"agent-sandbox: host {host!r} is {why}.\n".encode(),
        {"Content-Type": "text/plain; charset=utf-8"},
    )


def server_connect(data) -> None:
    """Refuse to dial any destination that resolves to a non-public address,
    whatever the allowlist says about its name. Fires once per upstream
    connection, before the socket is opened; setting data.server.error aborts it
    (mitmproxy checks .error immediately after this hook). This is the backstop
    the per-request name check cannot be: it sees the address actually dialed."""
    server = getattr(data, "server", None)
    address = getattr(server, "address", None)
    if not address:
        return
    host = address[0]
    reason = _forbidden_destination(host)
    if reason:
        _log_blocked(host, "DEST", reason)
        # Attributed through the tunnel's CONNECT token, when there was one (HTTPS);
        # a plain-HTTP request's token is not kept per connection, so its non-public
        # refusal is in blocked.log only.
        cid = getattr(getattr(data, "client", None), "id", None)
        _log_refused(_conn_token.get(cid) if cid is not None else None, host, "DEST", "non-public")
        server.error = (
            f"agent-sandbox: refused connection to a non-public address ({reason}). "
            f"The proxy only reaches public hosts on the allowlist."
        )


def responseheaders(flow: http.HTTPFlow) -> None:
    flow.response.stream = True
ADDON_EOF
ok "wrote $CONFIG_DIR/allowlist_addon.py"

# 7b. allowlist.txt: the generic starter is written only if absent (re-runs keep
# your edits). A profile's hosts are its dot-file's [allow], opened per launch.
if [[ -f "$CONFIG_DIR/allowlist.txt" ]]; then
  ok "$CONFIG_DIR/allowlist.txt already exists (kept as-is)"
else
  cat >"$CONFIG_DIR/allowlist.txt" <<'ALLOW_EOF'
# agent-sandbox allowlist
#
# One hostname per line. Lines starting with "#" are comments.
# A leading dot (".github.com") matches the host AND its subdomains.
# Edits take effect immediately — no restart needed.
#
# Blocked requests are logged to ~/.config/agent-sandbox/blocked.log;
# tail it (`tail -f ~/.config/agent-sandbox/blocked.log`) to see what
# the agent is trying to reach and add hosts here as needed. Hosts an agent
# profile needs (e.g. api.anthropic.com for claude) are not listed here: they are
# its dot-file's [allow] (profiles/<name>/agent-sandbox), opened for each launch.
#
# The allowlist gates PUBLIC hosts only. A host here that resolves to a
# non-public address -- loopback, a private/LAN range, or link-local (incl.
# cloud metadata 169.254.169.254) -- is still refused (502): the proxy runs on
# the host and never dials those. To reach a host-local service, use --host-port
# in strict mode, not this list. See docs/network.md.

# ---- Git / code hosting ----
github.com
api.github.com
codeload.github.com
objects.githubusercontent.com
raw.githubusercontent.com
.githubusercontent.com

# ---- Python packaging ----
pypi.org
files.pythonhosted.org

# ---- Node packaging ----
registry.npmjs.org

# ---- Conda / mamba ----
conda.anaconda.org
repo.anaconda.com
.conda-forge.org

# ---- Rust ----
crates.io
static.crates.io

# ---- Documentation an agent may need to consult ----
code.claude.com

# ---- Add more below as you hit 403s ----
ALLOW_EOF
  ok "wrote starter $CONFIG_DIR/allowlist.txt"
fi

# 7c. the proxy's port (#335): one account's proxy per port, so a second install on
# the host (another account's) cannot have 8888 while the first one's holds it. The
# unit and the engine read the number from $PROXY_PORT_FILE; the engine's
# AGENT_SANDBOX_PROXY_PORT overrides it per launch.
#   --proxy-port N   N.
#   a recorded port  kept, so a re-run never moves a working proxy; said, when
#                    something other than our running unit listens there.
#   neither          8888, unless a listener that is not our unit holds it (our unit
#                    is one that is active: an install from before the file existed
#                    listened on 8888); then the next free port above 8888.
# What listens is read from `ss -ltn` (iproute2, on every Ubuntu), else `netstat -ltn`:
# a listener at ANY address holds the port, since mitmdump cannot bind 127.0.0.1:N under
# a 0.0.0.0:N. With neither tool, a connect to 127.0.0.1:N (bash's /dev/tcp) stands in;
# it sees loopback and wildcard listeners, which are the ones in the way.
PROXY_PORT_FILE="$CONFIG_DIR/proxy-port"
listening_ports() {
  if command -v ss >/dev/null; then
    ss -ltn 2>/dev/null | awk 'NR > 1 { sub(/.*:/, "", $4); print $4 }'
  elif command -v netstat >/dev/null; then
    netstat -ltn 2>/dev/null | awk '$1 ~ /^tcp/ { sub(/.*:/, "", $4); print $4 }'
  else
    return 1
  fi
}
LISTENING="$(listening_ports)" && HAVE_LISTENING=1 || HAVE_LISTENING=0
port_busy() { # $1 = port
  if ((HAVE_LISTENING)); then
    grep -qx -- "$1" <<<"$LISTENING"
  else
    (echo >"/dev/tcp/127.0.0.1/$1") 2>/dev/null
  fi
}
our_unit_active() { systemctl --user is-active --quiet agent-sandbox-mitmproxy.service 2>/dev/null; }
PROXY_PORT_WHY=""
recorded_port=""
[[ -f "$PROXY_PORT_FILE" ]] && recorded_port="$(tr -d '[:space:]' <"$PROXY_PORT_FILE" || true)"
if [[ -n "$PROXY_PORT_ARG" ]]; then
  PROXY_PORT="$PROXY_PORT_ARG" PROXY_PORT_WHY="--proxy-port"
  if [[ "$PROXY_PORT" != "$recorded_port" ]] && port_busy "$PROXY_PORT"; then
    warn "127.0.0.1:$PROXY_PORT is already in use: the proxy will not start there until it is free"
  fi
elif proxy_port_ok "$recorded_port"; then
  PROXY_PORT="$recorded_port" PROXY_PORT_WHY="recorded by an earlier run"
  if port_busy "$PROXY_PORT" && ! our_unit_active; then
    warn "127.0.0.1:$PROXY_PORT is in use by something other than this account's proxy: re-run with --proxy-port N to move it"
  fi
else
  [[ -n "$recorded_port" ]] && warn "$PROXY_PORT_FILE holds '$recorded_port', not a port; choosing again"
  PROXY_PORT=8888 PROXY_PORT_WHY="the default"
  if port_busy 8888 && ! our_unit_active; then
    while port_busy "$PROXY_PORT" && ((PROXY_PORT < 65535)); do PROXY_PORT=$((PROXY_PORT + 1)); done
    PROXY_PORT_WHY="8888 is held by another listener; the next free port"
  fi
fi
printf '%s\n' "$PROXY_PORT" >"$PROXY_PORT_FILE"
chmod 0644 "$PROXY_PORT_FILE"
ok "proxy port $PROXY_PORT ($PROXY_PORT_WHY), in $PROXY_PORT_FILE"

# 7d. systemd user unit (static but for its paths and port; safe to overwrite)
cat >"$SYSTEMD_DIR/agent-sandbox-mitmproxy.service" <<'UNIT_EOF'
[Unit]
Description=mitmproxy enforcing allowlist for the agent sandbox
Documentation=file:@ENGINE@
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
# http2=false: mitmproxy's HTTP/2 path is pure Python and an order of magnitude
# slower than HTTP/1.1; with response streaming in the addon this is near-native.
ExecStart=@MITMDUMP@ \
    --listen-host 127.0.0.1 \
    --listen-port @PROXY_PORT@ \
    --set block_global=false \
    --set termlog_verbosity=info \
    --set flow_detail=0 \
    --set http2=false \
    -s %h/.config/agent-sandbox/allowlist_addon.py
Restart=on-failure
RestartSec=2s
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=default.target
UNIT_EOF
sed -i -e "s|@ENGINE@|$LAUNCH_TARGET|g" -e "s|@MITMDUMP@|$MITMDUMP|g" -e "s|@PROXY_PORT@|$PROXY_PORT|g" \
  "$SYSTEMD_DIR/agent-sandbox-mitmproxy.service"
ok "wrote $SYSTEMD_DIR/agent-sandbox-mitmproxy.service"

# ----- 8. systemd: reload, enable, start -----
# An account with no user manager -- one that never logs in interactively, a dedicated
# account for the sshd profile (#335) -- has nothing to start the unit: `systemctl
# --user` reaches none (asked read-only, a dry run too). That is a note, not an error:
# the unit is written above anyway, for a later login, and the sshd profile runs a proxy
# of its own at every launch, needing neither.
section "Systemd user service"
USER_MANAGER=1
systemctl --user show-environment >/dev/null 2>&1 || USER_MANAGER=0
if ((! USER_MANAGER)); then
  info "note: this account has no user manager (systemctl --user reaches none), so the proxy unit is written but not started."
  info "      The sshd profile (asb --profile sshd) runs a proxy of its own at every launch and needs no unit. For the other"
  info "      profiles, log in as this account (or: sudo loginctl enable-linger $(id -un)) and re-run install.sh."
else
  run_sys systemctl --user daemon-reload
  if ((DRY_RUN)); then
    info "(dry-run) would enable and (re)start agent-sandbox-mitmproxy.service"
  else
    systemctl --user enable agent-sandbox-mitmproxy.service >/dev/null 2>&1 || true
    systemctl --user restart agent-sandbox-mitmproxy.service
    sleep 1
    if systemctl --user is-active --quiet agent-sandbox-mitmproxy.service; then
      ok "agent-sandbox-mitmproxy.service is active"
    else
      warn "agent-sandbox-mitmproxy.service did not start; inspect: journalctl --user -u agent-sandbox-mitmproxy"
    fi
  fi
fi

# ----- 9. the commands: `asb` and `agent-sandbox`, pointing at the engine -----
# The sandbox is asked for by name (#151): `asb claude`. Nothing is put at the
# agent's own name any more, so `claude` stays Claude Code, installed however it
# was -- the native installer, a package, anything on PATH.

section "Commands (\`asb\` and \`agent-sandbox\` -> the engine)"

MANIFEST="$STATE_DIR/install.manifest"
manifest_lines=()

# place_command DIR NAME -- put a symlink to the engine at DIR/NAME, a dry run
# included (it installs into $HOME like the rest). The names are agent-sandbox's
# own, so a file there that is not ours is someone else's program of that name:
# left alone, and said so, never moved aside.
place_command() {
  local link="$1/$2"
  if is_our_launcher "$link"; then
    if [[ "$(readlink -f "$link")" != "$LAUNCH_TARGET" ]]; then
      ln -sfn "$LAUNCH_TARGET" "$link"
      ok "re-pointed $link -> $LAUNCH_TARGET"
    else
      ok "$link already points at the engine"
    fi
  elif [[ -L "$link" && ! -e "$link" ]]; then
    ln -sfn "$LAUNCH_TARGET" "$link"
    ok "replaced dangling symlink $link -> $LAUNCH_TARGET"
  elif [[ -e "$link" ]]; then
    warn "$link exists and is not agent-sandbox (left untouched)"
    info "Another program is called $2 here. Use the other name, or remove it and re-run."
    return 0
  else
    ln -sfn "$LAUNCH_TARGET" "$link"
    ok "symlinked $link -> $LAUNCH_TARGET"
  fi
  manifest_lines+=("command	$link	$(fingerprint "$link")")
}

# Always ~/.local/bin, the conventional home of a user's own commands, and never
# "the first writable directory on PATH": that can lie outside this HOME entirely.
target_dir="$HOME/.local/bin"
case ":$PATH:" in
  *":$target_dir:"*) ;;
  *)
    warn "$target_dir is not on your PATH, so \`asb\` will not be found yet. Add it:"
    info "    export PATH=\"\$HOME/.local/bin:\$PATH\"   # in your shell profile"
    ;;
esac
if ! mkdir -p -- "$target_dir" 2>/dev/null; then
  err "cannot create $target_dir, so there is nowhere to put \`asb\`.
    Create a writable directory, put it on your PATH, and re-run:
        mkdir -p $HOME/.local/bin
        export PATH=\"\$HOME/.local/bin:\$PATH\"   # add this to your shell profile"
fi
for name in agent-sandbox asb; do
  place_command "$target_dir" "$name"
done

# Does typing them now reach the engine? And is the agent's own command the agent?
for name in agent-sandbox asb; do
  if command -v "$name" >/dev/null; then
    resolved=$(readlink -f "$(command -v "$name")")
    if [[ "$resolved" == "$LAUNCH_TARGET" ]]; then
      ok "\`$name\` on PATH resolves to the agent-sandbox engine"
    else
      warn "\`$name\` on PATH resolves to $resolved, not the engine. Check: type -a $name"
    fi
  fi
done
for f in "${profiles[@]}"; do
  cmd=$(profile_query "$f" profile_command)
  [[ "$cmd" == */* ]] && continue # shipped with the profile (above)
  existing="$(command -v "$cmd" 2>/dev/null || true)"
  if [[ -n "$existing" ]] && is_our_launcher "$existing"; then
    warn "\`$cmd\` on PATH is agent-sandbox, not the agent ($existing). Remove it: rm $existing"
  elif [[ -n "$existing" ]]; then
    ok "\`$cmd\` is the agent itself ($existing); a sandboxed launch is: asb $cmd"
  else
    info "\`$cmd\` is not on PATH; asb runs it once it is (or: asb --profile $cmd /path/to/it)"
  fi
done

# Record what was done, with a fingerprint per path, so the uninstall undoes
# exactly this. A manifest states intent; the fingerprints are what let the
# uninstall tell "as I left it" from "changed since", and it refuses to act on
# anything that no longer matches.
if ((DRY_RUN)); then
  info "(dry-run) would record ${#manifest_lines[@]} manifest entries in $MANIFEST"
elif ((${#manifest_lines[@]})); then
  mkdir -p "$STATE_DIR"
  {
    printf '# agent-sandbox install manifest -- written by install.sh, read by --uninstall.\n'
    printf '# Each entry carries what the path was when we left it; the uninstall skips\n'
    printf '# anything that has changed since. Safe to delete: the uninstall then falls\n'
    printf '# back to searching, which is less exact.\n'
    printf 'version\t1\n'
    printf 'statedir\t%s\n' "$STATE_DIR"
    printf 'unit\t%s\t%s\n' "$SYSTEMD_DIR/agent-sandbox-mitmproxy.service" \
      "$(fingerprint "$SYSTEMD_DIR/agent-sandbox-mitmproxy.service")"
    printf '%s\n' "${manifest_lines[@]}"
  } >"$MANIFEST"
  ok "recorded $MANIFEST"
fi

# ----- 10. smoke test -----
section "Smoke tests"
if bwrap --ro-bind / / --unshare-user --unshare-pid -- /bin/true 2>/dev/null; then
  ok "bwrap can create user+pid namespaces"
else
  warn "bwrap user-namespace test failed — see the agent-sandbox header for AppArmor notes"
fi
# Verifies the contract of the default `proxy` net mode: HTTPS_PROXY-honouring
# clients reach allowlisted hosts and ONLY those. Both halves matter -- a proxy
# that answers but does not refuse is not enforcing anything. (Other net modes
# make different promises: `strict` additionally blocks raw sockets and host
# loopback -- checked just below when passt/nftables are present; `open` filters
# nothing; `none` has no network. The user picks the mode per launch and owns
# its residual risk.)
# api.github.com, in the starter allowlist: ANY HTTP status proves the request went out
# through the proxy -- 200, or 403/429 when GitHub rate-limits the runner's address
# (seen on CI) -- since only a refused or failed CONNECT gives no status (000). A
# profile's own hosts are opened per launch, not here;
# example.com is not in the starter allowlist, so it must be refused at CONNECT
# (curl gets no response, code 000). A non-000 code for example.com means the
# allowlist is not enforcing.
# The proxy serves sandbox sessions only: a request without a live session's token
# gets 407. So the checks speak as a session -- a probe session owned by this
# installer, in the session base the engine and the addon both use, removed after --
# and a last one, without a token, checks that an anonymous client is refused.
probe_token=""
proxy_get() { # $1 = url; echoes the HTTP code (000 = refused/failed)
  curl -sS --cacert "$PROXY_CA" --proxy "http://${probe_token:+$probe_token:x@}127.0.0.1:$PROXY_PORT" --max-time 15 \
    -o /dev/null -w '%{http_code}' "$1" 2>/dev/null || true
}
probe_session=""
probe_session_begin() {
  local base rt
  if [[ -n "${AGENT_SANDBOX_SESSION_BASE:-}" ]]; then
    base="$AGENT_SANDBOX_SESSION_BASE"
  else
    rt="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
    [[ -d "$rt" && -w "$rt" ]] || rt=/tmp
    base="$rt/agent-sandbox.$(id -u)"
  fi
  mkdir -p "$base" && chmod 700 "$base" || return 1
  probe_session="$(mktemp -d "$base/session.XXXXXX")" || return 1
  probe_token="$(head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n')"
  printf '%s %s\n' "$$" "$(awk '{print $22}' "/proc/$$/stat")" >"$probe_session/owner.id"
  printf '%s\n' "$probe_token" >"$probe_session/proxy.token"
  : >"$probe_session/allow.txt"
}
if ((DRY_RUN)); then
  info "(dry-run) proxy request skipped"
elif ((! USER_MANAGER)); then
  info "proxy check skipped: the unit is not running (no user manager; see above)"
elif ! probe_session_begin; then
  warn "could not make a probe session to check the proxy with; skipping the proxy check"
else
  reach_code="$(proxy_get https://api.github.com/)"
  case "$reach_code" in
    [1-5][0-9][0-9])
      ok "proxy reaches an allowlisted host (api.github.com) -- HTTP $reach_code"
      # The other half of the contract: a non-allowlisted host is refused.
      block_code=$(proxy_get https://example.com/)
      if [[ "$block_code" == 000 ]]; then
        ok "proxy refuses a non-allowlisted host (example.com blocked at CONNECT)"
      else
        warn "SECURITY: non-allowlisted example.com returned HTTP $block_code through the proxy — the allowlist is NOT enforcing; check $CONFIG_DIR/allowlist_addon.py is loaded"
      fi
      ;;
    000) warn "no answer through the proxy; check 'systemctl --user status agent-sandbox-mitmproxy' and that api.github.com is in $CONFIG_DIR/allowlist.txt" ;;
    *) warn "unexpected response from api.github.com via the proxy: '$reach_code'" ;;
  esac
  rm -rf -- "$probe_session"
  probe_token=""
  anon_code="$(curl -sS --cacert "$PROXY_CA" --proxy "http://127.0.0.1:$PROXY_PORT" --max-time 15 \
    -o /dev/null -w '%{http_connect}' https://api.github.com/ 2>/dev/null || true)"
  if [[ "$anon_code" == 407 ]]; then
    ok "proxy refuses a client with no session token (407)"
  else
    warn "SECURITY: a client with no session token got '$anon_code' through the proxy, not 407 -- a session's [deny] and retrieve-only can be bypassed; check $CONFIG_DIR/allowlist_addon.py is loaded"
  fi
fi

# Strict mode's contract (AGENT_SANDBOX_NET=strict): pasta gives the sandbox its
# own netns with an nftables rule that lets ONLY the proxy on the gateway out --
# so a tool ignoring HTTPS_PROXY, and host loopback services, cannot be reached.
# Exercise it for real, the same way the proxy check above does its mode: stand
# up the exact pasta+nft the engine uses and probe from inside. Only when its
# machinery is present (it is opt-in), never in dry-run, always bounded by a
# timeout, and only ever a warning -- proxy is the mode this install sets up.
strict_smoke() {
  local nft="$1" port="$2" out gwr lor rawr
  command -v pasta >/dev/null || {
    info "strict mode: passt not installed, skipping its check (needed only for AGENT_SANDBOX_NET=strict)"
    return 0
  }
  [[ -n "$nft" ]] || {
    info "strict mode: nftables not installed, skipping its check"
    return 0
  }
  # Can pasta create a namespace here? (Needs its AppArmor profile, section 4.)
  if ! timeout -k 1 8 pasta --config-net --quiet -- true >/dev/null 2>&1; then
    warn "strict mode: pasta cannot create a namespace here; AGENT_SANDBOX_NET=strict will not start"
    info "is /etc/apparmor.d/pasta loaded? (re-run this installer) or relax kernel.apparmor_restrict_unprivileged_userns"
    return 0
  fi
  # Inside pasta's netns, exactly as the engine's _as_launch_pasta does: read the
  # gateway pasta configured there, load the rule allowing only its proxy port,
  # then TCP-connect (via /dev/tcp, bounded) to the proxy at the gateway (must
  # reach), the same port on loopback (must NOT -- host loopback is not
  # mirrored), and an arbitrary host (must not).
  # shellcheck disable=SC2016
  out="$(timeout -k 2 20 pasta --config-net --quiet -T none -U none -t none -u none -- bash -c '
    nft=$1 port=$2
    gw=$(ip -4 route show default 2>/dev/null | sed -n "s/.*via \([0-9.]*\).*/\1/p" | head -1)
    [ -n "$gw" ] || { echo "gw=none"; exit 0; }
    printf "table inet agent_sandbox {\n chain output {\n  type filter hook output priority 0; policy drop\n  oifname \"lo\" accept\n  ip daddr %s tcp dport %s accept\n }\n}\n" "$gw" "$port" | "$nft" -f - || { echo "nft=failed"; exit 0; }
    pr() { timeout 4 bash -c "exec 3<>/dev/tcp/$1/$2" 2>/dev/null && echo REACHED || echo blocked; }
    echo "gw=$(pr "$gw" "$port")"
    echo "lo=$(pr 127.0.0.1 "$port")"
    echo "raw=$(pr 1.1.1.1 443)"
  ' agent-sandbox-strict-check "$nft" "$port" 2>/dev/null || true)"
  if [[ "$out" == *gw=none* ]]; then
    info "strict mode: no IPv4 gateway inside a test netns here, skipping its check"
    return 0
  fi
  if [[ "$out" == *nft=failed* ]]; then
    warn "strict mode: the egress firewall (nft) failed to load in a test netns; AGENT_SANDBOX_NET=strict would refuse to launch"
    return 0
  fi
  gwr="${out#*gw=}"
  gwr="${gwr%%$'\n'*}"
  lor="${out#*lo=}"
  lor="${lor%%$'\n'*}"
  rawr="${out#*raw=}"
  rawr="${rawr%%$'\n'*}"
  if [[ "$rawr" != blocked ]]; then
    warn "SECURITY: strict mode did NOT block raw egress in a test netns (1.1.1.1:443 was reachable) — the firewall is not enforcing"
  elif [[ "$gwr" != REACHED ]]; then
    warn "strict mode: the proxy at the netns gateway was not reachable from a test netns; strict would have no working egress (is the proxy up?)"
  elif [[ "$lor" == REACHED ]]; then
    warn "strict mode: a host loopback port (127.0.0.1:$port) was reachable from a test netns — host services are not isolated as strict promises"
  else
    ok "strict mode enforces its contract (only the proxy on the gateway is reachable; raw egress and host loopback blocked)"
  fi
  return 0
}
if ((DRY_RUN)); then
  info "(dry-run) strict-mode check skipped"
elif ((! USER_MANAGER)); then
  info "strict-mode check skipped: it needs the proxy, whose unit is not running (no user manager)"
else
  strict_smoke "$nftbin" "$PROXY_PORT"
fi

# ----- 11. summary -----
section "Done"
cat <<SUMMARY
Next steps:
  - Open a fresh shell (or \`hash -r\`) so \`asb\` is on PATH.
  - cd into a project and run:  asb claude
    (\`claude\` alone is Claude Code itself, not sandboxed.)
  - Tail blocked requests:  tail -f $CONFIG_DIR/blocked.log
  - Edit the allowlist:     \$EDITOR $CONFIG_DIR/allowlist.txt
  - Bypass proxy one-shot:  AGENT_SANDBOX_NET=open asb claude
SUMMARY
[[ "$PROXY_PORT" == 8888 ]] \
  || printf '  - The proxy listens on 127.0.0.1:%s, not 8888 (%s).\n' "$PROXY_PORT" "$PROXY_PORT_WHY"
